const startNewsExtraction = `-- name: StartNewsExtraction :one
INSERT INTO news_extractions (
    version_id, extractor_key, provider, model, prompt_version, schema_version,
    input_hash, status, attempts, last_attempt_at
)
VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', 1, $8)
ON CONFLICT (version_id, extractor_key) DO UPDATE SET
    input_hash = EXCLUDED.input_hash,
    status = 'pending',
    attempts = news_extractions.attempts + 1,
    last_attempt_at = EXCLUDED.last_attempt_at,
    updated_at = NOW()
WHERE news_extractions.status <> 'pending' OR news_extractions.last_attempt_at <= $9
RETURNING id, attempts
`

type StartNewsExtractionParams struct {
	VersionID     int64              `json:"version_id"`
	ExtractorKey  string             `json:"extractor_key"`
	Provider      string             `json:"provider"`
	Model         string             `json:"model"`
	PromptVersion string             `json:"prompt_version"`
	SchemaVersion string             `json:"schema_version"`
	InputHash     string             `json:"input_hash"`
	LastAttemptAt pgtype.Timestamptz `json:"last_attempt_at"`
	StaleBefore   pgtype.Timestamptz `json:"stale_before"`
}

type StartNewsExtractionRow struct {
	ID       int64 `json:"id"`
	Attempts int32 `json:"attempts"`
}

// Records an attempt before the model is called, so a crash still counts
// against the attempt limit. An attempt another refresh started after
// @stale_before is left alone and no row is returned: that refresh is
// extracting the version.
func (q *Queries) StartNewsExtraction(ctx context.Context, arg StartNewsExtractionParams) (StartNewsExtractionRow, error) {
	row := q.db.QueryRow(ctx, startNewsExtraction,
		arg.VersionID,
		arg.ExtractorKey,
		arg.Provider,
		arg.Model,
		arg.PromptVersion,
		arg.SchemaVersion,
		arg.InputHash,
		arg.LastAttemptAt,
		arg.StaleBefore,
	)
	var i StartNewsExtractionRow
	err := row.Scan(&i.ID, &i.Attempts)
	return i, err
}

const touchNewsEvent = `-- name: TouchNewsEvent :exec
UPDATE news_events SET
    first_reported_at = LEAST(first_reported_at, $1),
    last_reported_at = GREATEST(last_reported_at, $1),
    updated_at = NOW()
WHERE id = $2
`

type TouchNewsEventParams struct {
	ReportedAt pgtype.Timestamptz `json:"reported_at"`
	ID         int64              `json:"id"`
}

// Widens the event's reported span to a report that supports it.
func (q *Queries) TouchNewsEvent(ctx context.Context, arg TouchNewsEventParams) error {
	_, err := q.db.Exec(ctx, touchNewsEvent, arg.ReportedAt, arg.ID)
	return err
}
